<?php
include 'db.php';
$success = '';
$error = '';

// Handle form submission BEFORE any output
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
  $name = $_POST['Name'] ?? '';
  $phone = $_POST['Contact'] ?? '';
  $email = $_POST['email'] ?? '';
  $subject = $_POST['Subject'] ?? '';
  $message = $_POST['Message'] ?? '';

  // Insert into contact_requests table
  $stmt = $conn->prepare("INSERT INTO contact_requests (name, email, phone, subject, message, date_submitted, status) VALUES (?, ?, ?, ?, ?, NOW(), 'pending')");
  if ($stmt) {
    $stmt->bind_param("sssss", $name, $email, $phone, $subject, $message);
    if ($stmt->execute()) {
      // Redirect to avoid duplicate submission on refresh
      header('Location: contact.php?success=1');
      exit();
    } else {
      $error = "Error submitting your message. Please try again.";
    }
    $stmt->close();
  } else {
    $error = "Database error.";
  }
}

if (isset($_GET['success']) && $_GET['success'] == 1) {
  $success = "Thank you for contacting us! We have received your message.";
}

require_once('header.php');
?>

